    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS" },
        new() { Id = 2, Name = "Mathematics", Code = "MATH" },
        new() { Id = 3, Name = "Physics", Code = "PHYS" },
        new() { Id = 4, Name = "English", Code = "ENG" },
        new() { Id = 5, Name = "History", Code = "HIST" }
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control structures, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a PhD in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and CS education.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an associate professor specializing in algorithm optimization. He previously worked at Google Research on large-scale graph algorithms.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 350", Title = "Database Systems", Description = "Principles of database design, relational algebra, SQL, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez has extensive industry experience at Oracle and Microsoft before joining academia. She specializes in distributed database systems.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 4, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, differentiation of single-variable functions, and introduction to integration. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Williams", InstructorBio = "Dr. Williams is a tenured professor with over 20 years of experience teaching undergraduate mathematics. He authored the textbook 'Calculus Made Clear'.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications in computer science and physics.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura's research is in applied linear algebra and numerical methods. She collaborates with the physics department on quantum computing projects.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a statistician who consults with major healthcare organizations on clinical trial design.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 7, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "TTh 9:00–10:15 AM + Lab F 2:00–4:50 PM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim is an experimental physicist with publications in Nature and Science. He is passionate about making physics accessible to all students.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab W 2:00–4:50 PM", InstructorName = "Dr. Lisa Patel", InstructorBio = "Dr. Patel researches superconducting materials and has received multiple NSF grants for her work in condensed matter physics.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 9, CourseCode = "ENG 101", Title = "College Composition", Description = "Development of academic writing skills including argumentation, research methods, and critical analysis of texts.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", InstructorName = "Prof. Margaret O'Brien", InstructorBio = "Prof. O'Brien is an award-winning author and writing instructor who emphasizes clear, purposeful communication in all forms.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a scholar of 20th-century American fiction with a focus on the Harlem Renaissance and postmodern narratives.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 11, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural exchanges from prehistory through the late medieval period.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Angela Martinez", InstructorBio = "Dr. Martinez specializes in ancient Mediterranean civilizations and has led archaeological digs in Greece and Turkey.", DepartmentId = 5, IsFeatured = false },
        new() { Id = 12, CourseCode = "HIST 202", Title = "Modern World History", Description = "From the Age of Exploration through the 21st century: colonialism, revolutions, world wars, and globalization.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. William Hayes", InstructorBio = "Dr. Hayes is a diplomatic historian who previously served as a historical consultant for the State Department.", DepartmentId = 5, IsFeatured = true }
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

