@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="row mb-4 mt-3">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="SearchTerm" @bind:event="oninput" @onkeyup="ApplyFilters" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="SelectedDepartmentId" @bind:after="ApplyFilters">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @if (!_courses.Any())
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th>Schedule</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        <tr>
                            <td>@course.CourseCode</td>
                            <td>@course.Title</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td>@course.Schedule</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }
    private List<Course> _courses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        if (DepartmentId.HasValue)
            SelectedDepartmentId = DepartmentId.Value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        _courses = CatalogService.SearchCourses(SearchTerm, SelectedDepartmentId > 0 ? SelectedDepartmentId : null);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

<div class="container">
    @if (_course is null)
    {
        <div class="alert alert-warning">Course not found.</div>
        <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
                <li class="breadcrumb-item active">@_course.CourseCode</li>
            </ol>
        </nav>

        <h1>@_course.CourseCode — @_course.Title</h1>

        <div class="row mt-4">
            <div class="col-md-8">
                <h3>Description</h3>
                <p>@_course.Description</p>

                <h3 class="mt-4">Schedule</h3>
                <p><strong>@_course.Schedule</strong></p>

                <h3 class="mt-4">Credits</h3>
                <p>@_course.Credits credit hours</p>
            </div>
            <div class="col-md-4">
                <div class="card">
                    <div class="card-body">
                        <h4 class="card-title">Instructor</h4>
                        <h5>@_course.InstructorName</h5>
                        <p class="text-muted">@_course.InstructorBio</p>
                    </div>
                </div>
                <div class="mt-3">
                    <a href="/enroll?courseId=@_course.Id" class="btn btn-primary w-100">Enroll in This Course</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request below. You will be notified of approval via your university email.</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will receive a confirmation email shortly.</p>
            <a href="/courses" class="btn btn-primary">Back to Courses</a>
        </div>
    }
    else
    {
        <EditForm Model="_request" OnValidSubmit="HandleSubmit" FormName="enrollment" class="mt-4" style="max-width: 600px;">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" class="form-control" @bind-Value="_request.StudentName" />
                <ValidationMessage For="() => _request.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" class="form-control" @bind-Value="_request.StudentId" placeholder="e.g. 12345678" />
                <ValidationMessage For="() => _request.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseSelect" class="form-label">Course</label>
                <InputSelect id="courseSelect" class="form-select" @bind-Value="_request.CourseId">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id">@course.CourseCode — @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _request.CourseId" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-secondary ms-2">Cancel</a>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private EnrollmentRequest _request = new();
    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();
        if (CourseId.HasValue)
            _request.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(_request.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.CourseCode} — {course.Title}" : "Unknown";
        CatalogService.SubmitEnrollment(_request);
        _submitted = true;
    }
}

